import React from 'react';
import { usePage } from '../../context/PageContext';
import classNames from 'classnames';

interface SidebarTreeProps {}

const SidebarTree: React.FC<SidebarTreeProps> = () => {
  const { pages, selectedPageId, setSelectedPageId } = usePage();

  const renderTree = (pages: typeof pages) => {
    return (
      <ul>
        {pages.map(page => (
          <li key={page.id}>
            <button
              className={classNames('sidebar-page', {
                'selected': selectedPageId === page.id,
              })}
              onClick={() => setSelectedPageId(page.id)}
            >
              {page.title}
            </button>
            {page.children && page.children.length > 0 && (
              <div className="sidebar-children">
                {renderTree(page.children)}
              </div>
            )}
          </li>
        ))}
      </ul>
    );
  };

  return (
    <nav className="sidebar">
      <h2>Pages</h2>
      {renderTree(pages)}
    </nav>
  );
};

export default SidebarTree;

import React, { createContext, useState, useContext, ReactNode } from 'react';

interface Page {
  id: string;
  title: string;
  content: string;
  children?: Page[];
}

interface PageContextProps {
  pages: Page[];
  setPages: React.Dispatch<React.SetStateAction<Page[]>>;
  selectedPageId: string | null;
  setSelectedPageId: React.Dispatch<React.SetStateAction<string | null>>;
  currentPageContent: string;
  setCurrentPageContent: React.Dispatch<React.SetStateAction<string>>;
}

const PageContext = createContext<PageContextProps | undefined>(undefined);

export const PageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [pages, setPages] = useState<Page[]>([
    {
      id: '1',
      title: 'Welcome',
      content: '',
      children: [
        {
          id: '1-1',
          title: 'Getting Started',
          content: '',
        },
      ],
    },
    {
      id: '2',
      title: 'About',
      content: '',
    },
  ]);
  const [selectedPageId, setSelectedPageId] = useState<string | null>('1');
  const [currentPageContent, setCurrentPageContent] = useState<string>('');

  return (
    <PageContext.Provider value={{ pages, setPages, selectedPageId, setSelectedPageId, currentPageContent, setCurrentPageContent }}>
      {children}
    </PageContext.Provider>
  );
};

export const usePage = () => {
  const context = useContext(PageContext);
  if (!context) {
    throw new Error('usePage must be used within a PageProvider');
  }
  return context;
};

